import React, { useState, useEffect } from 'react';
import api from '../services/api';
import { formatLocalDate } from '../utils/dateUtils';

const LinksInscripcion = () => {
  const [ofertas, setOfertas] = useState([]);
  const [loading, setLoading] = useState(true);
  const [copiado, setCopiado] = useState(null);
  const [usuario, setUsuario] = useState(null);

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem('user') || '{}');
    setUsuario(user);
    cargarMisOfertas();
  }, []);

  const cargarMisOfertas = async () => {
    try {
      const response = await api.get('/ofertas/mis-ofertas');
      setOfertas(response.data.data || []);
    } catch (error) {
      console.error('Error cargando mis ofertas:', error);
    } finally {
      setLoading(false);
    }
  };

  const copiarLink = (link) => {
    const urlCompleta = `http://localhost:3000${link}`;
    navigator.clipboard.writeText(urlCompleta);
    setCopiado(link);
    setTimeout(() => setCopiado(null), 2000);
  };

  const abrirLink = (link) => {
    window.open(`http://localhost:3000${link}`, '_blank');
  };

  const descargarPDF = async (ofertaId) => {
    try {
      const token = localStorage.getItem('token');
      const response = await api.get(`/ofertas/${ofertaId}/pdf`, {
        responseType: 'blob',
        headers: { Authorization: `Bearer ${token}` }
      });
      
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `ficha-${ofertaId}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.remove();
    } catch (error) {
      console.error('Error descargando PDF:', error);
      alert('Error al descargar el PDF');
    }
  };

  const crearNuevaOferta = () => {
    window.location.href = '/dashboard';
  };

  const getColorPorCupos = (disponibles, maximo) => {
    const porcentaje = (disponibles / maximo) * 100;
    if (porcentaje >= 80) return 'bg-secondary/10 text-secondary';
    if (porcentaje >= 50) return 'bg-warning/10 text-warning';
    return 'bg-error-container text-on-error-container';
  };

  const totalInscritos = ofertas.reduce((sum, o) => sum + (o.cupos_disponibles || 0), 0);
  const totalCupos = ofertas.reduce((sum, o) => sum + (o.cupo_maximo || 0), 0);
  const cuposRestantes = totalCupos - totalInscritos;

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#006c49] mx-auto mb-4"></div>
          <p className="text-[#45474c]">Cargando mis ofertas...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-[1440px] mx-auto">
      {/* Header Section */}
      <div className="mb-8">
        <h1 className="text-3xl md:text-4xl font-semibold text-[#091426] mb-4">
          🔗 Mis Ofertas - Links de Inscripción
        </h1>
        <div className="bg-[#eff4ff] border border-[#c5c6cd] rounded-lg p-4 flex items-center justify-between flex-wrap gap-4">
          <div className="flex items-center gap-2">
            <span className="material-symbols-outlined text-[#006c49]">account_circle</span>
            <span className="text-base text-[#0b1c30]">
              Mostrando ofertas de: <strong className="text-[#0b1c30]">{usuario?.nombreUsuario || usuario?.nombre || 'Usuario'}</strong>
            </span>
          </div>
          <div className="flex gap-2">
            <button 
              onClick={crearNuevaOferta}
              className="bg-[#006c49] text-white px-6 py-2 rounded-lg font-medium text-sm flex items-center gap-2 hover:opacity-90 transition-opacity"
            >
              <span className="material-symbols-outlined text-base">add_circle</span>
              Crear Oferta
            </button>
          </div>
        </div>
      </div>

      {/* Empty State */}
      {ofertas.length === 0 && (
        <div className="py-20 flex flex-col items-center justify-center text-center">
          <div className="w-24 h-24 bg-[#dce9ff] rounded-full flex items-center justify-center mb-6">
            <span className="material-symbols-outlined text-5xl text-[#45474c]">folder_off</span>
          </div>
          <h3 className="text-2xl font-semibold text-[#091426] mb-2">No tienes ofertas creadas aún.</h3>
          <p className="text-base text-[#45474c] mb-8 max-w-md">
            Ve a 'Crear Oferta' para comenzar a gestionar tus links de inscripción y cupos disponibles.
          </p>
          <button 
            onClick={crearNuevaOferta}
            className="bg-[#006c49] text-white px-8 py-3 rounded-xl font-bold hover:shadow-lg transition-all active:scale-95"
          >
            Crear mi primera oferta
          </button>
        </div>
      )}

      {/* Stats Dashboard */}
      {ofertas.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="md:col-span-2 text-white p-6 rounded-2xl flex flex-col justify-between min-h-[200px] overflow-hidden relative bg-[#006c49] text-white">
            <div className="z-10">
              <span className="text-xs font-medium opacity-70">Total Inscritos</span>
              <h2 className="text-4xl md:text-5xl font-bold mt-1">{totalInscritos}</h2>
            </div>
            <div className="z-10 flex gap-3 mt-4">
              <div className="bg-[#006c49]/30 px-4 py-1 rounded-full text-xs font-medium">
                +12% este mes
              </div>
            </div>
            <div className="absolute -right-10 -bottom-10 w-48 h-48 bg-white/10 rounded-full blur-3xl"></div>
          </div>
          <div className="bg-[#d3e4fe] p-6 rounded-2xl border border-[#c5c6cd] flex flex-col justify-between">
            <span className="text-xs font-medium text-[#45474c]">Ofertas Activas</span>
            <h2 className="text-3xl font-semibold text-[#091426] mt-1">{ofertas.length}</h2>
            <div className="w-full bg-[#c5c6cd] h-1 rounded-full overflow-hidden mt-3">
              <div className="bg-[#006c49] h-full" style={{ width: `${Math.min(100, (ofertas.length / 20) * 100)}%` }}></div>
            </div>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-[#c5c6cd] flex flex-col justify-between shadow-sm">
            <span className="text-xs font-medium text-[#45474c]">Cupos Restantes</span>
            <h2 className="text-3xl font-semibold text-[#006c49] mt-1">{cuposRestantes}</h2>
            <p className="text-sm text-[#45474c] mt-3">Promedio: {(cuposRestantes / ofertas.length || 0).toFixed(1)}/oferta</p>
          </div>
        </div>
      )}

      {/* Grid of Cards */}
      {ofertas.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {ofertas.map((oferta) => {
            const porcentajeCupos = ((oferta.cupos_disponibles || 0) / (oferta.cupo_maximo || 1)) * 100;
            const cuposColorClass = porcentajeCupos >= 80 ? 'bg-[#6cf8bb]/30 text-[#005236]' : 
                                    porcentajeCupos >= 50 ? 'bg-orange-100 text-orange-700' : 
                                    'bg-[#ffdad6] text-[#93000a]';
            
            return (
              <div key={oferta._id} className="bg-white rounded-xl border border-[#c5c6cd] shadow-sm overflow-hidden transition-all duration-300 hover:shadow-md">
                <div className="p-5 bg-[#e5eeff]/30 border-b border-[#c5c6cd] flex justify-between items-start">
                  <div>
                    <h3 className="text-xl font-semibold text-[#091426] mb-1">
                      {oferta.programa_formacion?.nombre_programa || 'Programa sin nombre'}
                    </h3>
                    <span className="text-xs font-medium bg-[#6cf8bb]/30 text-[#005236] px-2 py-0.5 rounded">
                      ID: {oferta.programa_formacion?.codigo || 'N/A'}
                    </span>
                  </div>
                  <div className="text-right">
                    <span className="block text-xs text-[#45474c] uppercase tracking-wider mb-1">Cupos</span>
                    <span className={`${cuposColorClass} font-bold px-3 py-1 rounded-full text-sm`}>
                      {oferta.cupos_disponibles || 0}/{oferta.cupo_maximo || 0}
                    </span>
                  </div>
                </div>
                
                <div className="p-5 space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs text-[#45474c] mb-1">Fechas</label>
                      <p className="text-sm flex items-center gap-1">
                        <span className="material-symbols-outlined text-sm">calendar_today</span>
                        {formatLocalDate(oferta.fechas?.inicio)} - {formatLocalDate(oferta.fechas?.fin)}
                      </p>
                    </div>
                    <div>
                      <label className="block text-xs text-[#45474c] mb-1">Municipio</label>
                      <p className="text-sm flex items-center gap-1">
                        <span className="material-symbols-outlined text-sm">location_on</span>
                        {oferta.ubicacion?.municipio?.nombre || 'N/A'}
                      </p>
                    </div>
                  </div>
                  
                  <div>
                    <label className="block text-xs text-[#45474c] mb-1">Coordinador Asignado</label>
                    <p className="text-sm font-medium">{oferta.coordinador_asignado?.nombre || usuario?.coordinadorAsignado?.nombre || 'N/A'}</p>
                  </div>
                  
                  <div className="mt-3">
                    <label className="block text-xs text-[#45474c] mb-2 uppercase tracking-tight font-bold">Enlace de Registro</label>
                    <div className="bg-[#f8f9ff] border border-[#c5c6cd] rounded-lg p-3 text-sm text-[#45474c] flex items-center overflow-hidden">
                      <span className="truncate">localhost:3000{oferta.link_inscripciones || '/inscribirse/error'}</span>
                    </div>
                  </div>
                </div>
                
                <div className="p-4 bg-[#eff4ff] border-t border-[#c5c6cd] grid grid-cols-3 gap-2">
                  <button 
                    onClick={() => copiarLink(oferta.link_inscripciones)}
                    className={`flex items-center justify-center gap-2 font-medium py-2 rounded-lg transition-all active:scale-95 ${
                      copiado === oferta.link_inscripciones 
                        ? 'bg-[#006c49] text-white' 
                        : 'bg-[#bcc7de] text-[#111c2d] hover:bg-[#d8e3fb]'
                    }`}
                  >
                    <span className="material-symbols-outlined text-base">
                      {copiado === oferta.link_inscripciones ? 'check' : 'content_copy'}
                    </span>
                    {copiado === oferta.link_inscripciones ? 'Copiado' : 'Copiar'}
                  </button>
                  <button 
                    onClick={() => abrirLink(oferta.link_inscripciones)}
                    className="flex items-center justify-center gap-2 bg-[#6cf8bb] text-[#005236] font-medium py-2 rounded-lg hover:bg-[#4edea3] transition-all active:scale-95"
                  >
                    <span className="material-symbols-outlined text-base">open_in_new</span>
                    Abrir
                  </button>
                  <button 
                    onClick={() => descargarPDF(oferta._id)}
                    className="flex items-center justify-center gap-2 border border-[#ba1a1a] text-[#ba1a1a] font-medium py-2 rounded-lg hover:bg-[#ba1a1a]/10 transition-all active:scale-95"
                  >
                    <span className="material-symbols-outlined text-base">picture_as_pdf</span>
                    PDF
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Help Section */}
      {ofertas.length > 0 && (
        <div className="mt-12 grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="p-5 bg-white rounded-xl border border-[#c5c6cd] flex items-start gap-4">
            <div className="w-10 h-10 bg-[#6cf8bb]/20 rounded-lg flex items-center justify-center">
              <span className="material-symbols-outlined text-[#006c49]">info</span>
            </div>
            <div>
              <h4 className="font-semibold text-[#091426] mb-1">¿Cómo compartir el enlace de inscripción?</h4>
              <p className="text-sm text-[#45474c]">
                Copia el enlace de cada oferta y compártelo con los aspirantes. Ellos podrán registrarse directamente en el formulario de inscripción.
              </p>
            </div>
          </div>
          <div className="p-5 bg-white rounded-xl border border-[#c5c6cd] flex items-start gap-4">
            <div className="w-10 h-10 bg-[#ffdad6]/20 rounded-lg flex items-center justify-center">
              <span className="material-symbols-outlined text-[#ba1a1a]">notifications_active</span>
            </div>
            <div>
              <h4 className="font-semibold text-[#091426] mb-1">Seguimiento de Cupos</h4>
              <p className="text-sm text-[#45474c]">
                Los cupos se actualizan automáticamente a medida que los aspirantes completan su inscripción.
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default LinksInscripcion;
